parameters.jsCode:
const realResults = items
  .filter(item => item.json && (item.json.document || item.json.pageContent || (item.json.metadata && item.json.metadata.candidate_id)))
  .map(item => {
    const doc = item.json.document || item.json;
    const metadata = doc.metadata || item.json.metadata || {};
    return {
      candidate_id: metadata.candidate_id || null,
      full_name: metadata.full_name || null,
      email: metadata.email || null,
      score: item.json.score !== undefined ? item.json.score : null,
      snippet: (doc.pageContent || '').slice(0, 300)
    };
  })
  .filter(r => r.candidate_id !== null);

return [{ json: { count: realResults.length, results: realResults } }];

